typedef float rational_t;

class vector4d
{
public:
  rational_t x, y, z, w;
  inline vector4d(rational_t _x, rational_t _y, rational_t _z, rational_t _w)
    : x(_x), y(_y), z(_z), w(_w) {}
};

class matrix4x4
{
public:
  typedef rational_t T;
  typedef vector4d row;
  row x __attribute__((aligned(16)));
  row y;
  row z;
  row w;
  inline matrix4x4(
        T _00, T _01, T _02, T _03,
        T _10, T _11, T _12, T _13,
        T _20, T _21, T _22, T _23,
        T _30, T _31, T _32, T _33 )
    : x(_00, _01, _02, _03), y(_10, _11, _12, _13),
      z(_20, _21, _22, _23), w(_30, _31, _32, _33) {}
};

class hw_rasta
{
  static hw_rasta* instance;
public:
  static inline hw_rasta* inst() { return instance; }
  int get_screen_width() const;
  int get_screen_height() const;
  void set_cop(float x, float y, float min_z=0.0f, float max_z=1.0f);
};

class geometry_manager
{
  char released_layout[0x74];
public:
  enum xform_t
  {
    XFORM_LOCAL_TO_WORLD,
    XFORM_WORLD_TO_VIEW,
    XFORM_VIEW_TO_WORLD,
    XFORM_VIEW_TO_PROJECTION,
    XFORM_PROJECTION_TO_SCREEN
  };
  float cop_x, cop_y, cop_min_z, cop_max_z, cop_scale_z;
  void set_xform(xform_t xform, const matrix4x4& matrix);
  void set_cop(float x, float y, float min_z, float max_z);
};

void geometry_manager::set_cop(float x, float y, float min_z, float max_z)
{
  cop_x = x;
  cop_y = y;
  cop_min_z = min_z;
  cop_max_z = max_z;
  cop_scale_z = max_z-min_z;

  int width  = hw_rasta::inst()->get_screen_width();
  int height = hw_rasta::inst()->get_screen_height();

  matrix4x4 viewport( width*0.5f, 0,           0, 0,
                      0,         -height*0.5f, 0, 0,
                      0,          0,           1, 0,
                      x,          y,           0, 1 );

  set_xform(XFORM_PROJECTION_TO_SCREEN,viewport);

  hw_rasta::inst()->set_cop(x,y,min_z,max_z);
}
